CREATE TABLE IF NOT EXISTS receipts (receipt_id TEXT PRIMARY KEY, source_type TEXT NOT NULL, source_ref TEXT NOT NULL, content TEXT NOT NULL, captured_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (evidence_id TEXT PRIMARY KEY, receipt_id TEXT NOT NULL REFERENCES receipts(receipt_id), source_type TEXT NOT NULL, source_ref TEXT NOT NULL, content_hash TEXT, captured_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_candidates (candidate_id TEXT PRIMARY KEY, receipt_id TEXT NOT NULL REFERENCES receipts(receipt_id), claim TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('PERSONAL','WORKSPACE')), confidence REAL NOT NULL CHECK(confidence >= 0 AND confidence <= 1), source TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PENDING','CONFLICT')));
CREATE TABLE IF NOT EXISTS memory_claims (claim_id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES memory_candidates(candidate_id), claim TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('PERSONAL','WORKSPACE')), authorization TEXT NOT NULL, confidence REAL NOT NULL, source TEXT NOT NULL, outcome TEXT NOT NULL, created_at TEXT NOT NULL, reviewed_at TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS claim_evidence (claim_id TEXT NOT NULL REFERENCES memory_claims(claim_id), evidence_id TEXT NOT NULL REFERENCES evidence(evidence_id), PRIMARY KEY(claim_id,evidence_id));
CREATE TABLE IF NOT EXISTS outcomes (outcome_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES memory_claims(claim_id), outcome TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forget_tombstones (claim_id TEXT PRIMARY KEY, forgotten_at TEXT NOT NULL);
